-- sql/2026-10-16_objets_dd2024_srd_sp-po5b.sql
-- SP-PO5b — Objets magiques DD2024 : retranscription intégrale des descriptions du SRD 5.2.1
--
-- Source : FR_SRD_CC_v5.2.1-objets_magiques.pdf, section « Objets magiques de A à Z ».
--
-- CONTEXTE : les descriptions importées par les étapes précédentes (SP-IM9a à IM9c) avaient perdu une
-- partie du texte du SRD :
--   * les tableaux (coût des sorts d'un bâton ou d'une baguette, tables d'effets, tailles d'un tapis volant,
--     table de rareté des parchemins…) étaient aplatis en paragraphes illisibles, ou absents — et les
--     déclinaisons d'une entrée générique (anneau de résistance, parchemin de sort…) n'en portaient aucun ;
--   * des paragraphes fusionnés (Armure d'invulnérabilité + Armure de cuir clouté enchantée, Chèvre voyageuse
--     + Chèvre terrifiante…), des titres de capacité collés au paragraphe précédent ;
--   * des traits d'union avalés (« Reportezvous », « ellemême », « Mortvivant ») ;
--   * les profils inclus au texte (Mouche géante, Avatar de la Mort) absents ;
--   * la ligne 96–00 du chapeau mille-sorts tronquée, et « Yeux de lynx » absent de la base.
--
-- MÉTHODE : chaque description est reconstruite à partir du texte du PDF ; chaque tableau devient une ligne de
-- dd_tableaux appelée par le tag [[tab:slug]]. Les déclinaisons (120) reçoivent le texte commun de leur
-- entrée générique, la table qui s'y rattache et leur propre paragraphe. Catégorie, rareté et harmonisation
-- ont été contrôlées contre la ligne de type du SRD : aucun écart, elles ne sont pas touchées.
--
-- IDEMPOTENCE : tableaux en INSERT … ON DUPLICATE KEY UPDATE (clé slug + ruleset) ; objets mis à jour PAR NOM
-- (jamais par id : les ids diffèrent entre le local et OVH) ; l'ajout d'« Yeux de lynx » est gardé par un
-- NOT EXISTS. Rejouable. Pas de DELIMITER.

SET NAMES utf8mb4;

SET @rs  := (SELECT var_id FROM dd_variables WHERE var_cat = 'ruleset' AND var_valeur = 'DD2024' LIMIT 1);
SET @res := (SELECT res_id FROM dd_ressources WHERE res_abreviation = 'SRD 5.2.1' AND res_ruleset_var_id = @rs AND res_j_id IS NULL LIMIT 1);
SET @now := NOW();

START TRANSACTION;

-- ------------------------------------------------------------
-- 1. Tableaux (44)
-- ------------------------------------------------------------
