UPDATE dd_objets_magiques om
  JOIN tmp_om_po5b t ON t.t_nom = om.om_nom
   SET om.om_description = t.t_desc
 WHERE om.om_ruleset_var_id = @rs AND om.om_res_id = @res;

DROP TEMPORARY TABLE IF EXISTS tmp_om_po5b;

-- ------------------------------------------------------------
-- 3. Yeux de lynx (absent de la base)
-- ------------------------------------------------------------
INSERT INTO dd_objets_magiques (om_nom, om_com_id, om_fom_id, om_description, om_harmonisation, om_rarete,
                               om_visible, om_public, om_res_id, om_camp_id, om_ruleset_var_id)
SELECT 'Yeux de lynx',
       (SELECT com_id FROM dd_categorie_objet_magique WHERE com_slug = 'objets-merveilleux' AND com_ruleset_var_id = @rs LIMIT 1),
       2, '<p>Ces lentilles en cristal s’appliquent sur les yeux. Tant que vous les portez, vous avez l’Avantage aux tests de Sagesse (Perception) qui reposent sur la vue. Dans des conditions de bonne visibilité, vous pouvez distinguer les détails de créatures et d’objets à très longue distance, tant que leur largeur est d’au moins 60 cm.</p>', 0,
       (SELECT omr_id FROM dd_objets_magiques_rarete WHERE omr_nom = 'Peu courant' AND omr_ruleset_var_id = @rs LIMIT 1),
       1, 0, @res, NULL, @rs
  FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM dd_objets_magiques WHERE om_nom = 'Yeux de lynx' AND om_ruleset_var_id = @rs AND om_res_id = @res);

COMMIT;
